import{KKPHIM_API}from"../config.js";import{cachedFetch}from"../js/cache-utils.js";const IMG_CDN="https://phimimg.com";export function searchBar(){const e=document.querySelector(".search__input"),t=document.querySelector(".search__dropdown");let s;e.addEventListener("input",()=>{const r=e.value.trim();if(clearTimeout(s),!r)return t.innerHTML="",void t.classList.remove("search__dropdown--active");s=setTimeout(async()=>{try{const e=await async function(e){const t=await cachedFetch(`${KKPHIM_API}/v1/api/tim-kiem?keyword=${encodeURIComponent(e)}`,12e4);return(t?.data?.items||[]).map(e=>({...e,media_type:(e.category||[]).some(e=>"phim-bo"===e.slug||"tv-shows"===e.slug)?"tv":"movie"}))}(r);!function(e){if(t.innerHTML="",!e.length)return t.classList.remove("search__dropdown--active");t.classList.add("search__dropdown--active"),e.forEach(e=>{if(!e.poster_url)return;const s=document.createElement("div");s.classList.add("search__result");const r=e.poster_url.startsWith("http")?e.poster_url:`${IMG_CDN}/${e.poster_url}`,c=e.name||"Không rõ",i=e.origin_name||"",n=e.year||"",a="movie"===e.media_type?`Phim lẻ • ${n}`:`Phim bộ • ${n}`;s.innerHTML=`\n        <img class="search__result-img" src="${r}" alt="${c}">\n        <div class="search__result-info">\n          <div class="search__result-title">${c}</div>\n          ${i&&i!==c?`<div class="search__result-subtitle">${i}</div>`:""}\n          <div class="search__result-meta">${a}</div>\n        </div>\n      `,s.addEventListener("click",()=>{t.classList.remove("search__dropdown--active"),window.location.href=`DetailPage.html?slug=${e.slug}`}),t.appendChild(s)})}(e.slice(0,10))}catch(e){console.error(e)}},400)}),e.addEventListener("keydown",t=>{if("Enter"===t.key){t.preventDefault();const s=e.value.trim();s&&(window.location.href=`SearchPage.html?query=${encodeURIComponent(s)}`)}}),document.addEventListener("click",e=>{e.target.closest(".search")||t.classList.remove("search__dropdown--active")})}